import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十一卦 損 山澤損 艮上兌下","description":"周易 - 第四十一卦 損 山澤損 艮上兌下","frontmatter":{"title":"第四十一卦 損 山澤損 艮上兌下","description":"周易 - 第四十一卦 損 山澤損 艮上兌下"},"headers":[],"relativePath":"classics/zhouyi/042.md","filePath":"classics/zhouyi/042.md"}'),l={name:"classics/zhouyi/042.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="損" tabindex="-1">損 <a class="header-anchor" href="#損" aria-label="Permalink to “損”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>有孚，元吉，無咎，可貞，利有攸往？曷之用，二簋可用享。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>損，損下益上，其道上行。損而有孚，元吉，無咎，可貞，利有攸往。曷之用？二簋可用享；二簋應有時。損剛益柔有時，損益盈虛，與時偕行。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山下有澤，損；君子以懲忿窒欲。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>已事遄往，無咎，酌損之。象曰：已事 遄往，尚合志也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>利貞，徵兇，弗損益之。象曰：九二利貞，中以為志也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>三人行，則損一人；一人行，則得其友。象曰：一人行，三則疑也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>損其疾，使遄有喜，無咎。象曰：損其疾，亦可喜也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>或益之，十朋之龜弗克違，元吉。象曰：六五元吉，自上佑也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>弗損益之，無咎，貞吉，利有攸往，得臣無家。象曰：弗損益之，大得志也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
